import torch


def gen_inputs(ctx, device):
    shape = tuple(ctx["x__shape"])
    dtype = getattr(torch, ctx["x__dtype"])
    is_bool = (dtype == torch.bool) or (str(dtype) in ("torch.bool", "bool"))
    if is_bool:
        x = torch.randint(0, 2, size=shape, dtype=dtype, device=device)
    else:
        x = torch.randint(
            low=-0x7FFF, high=0x7FFF, size=shape, dtype=dtype, device="cpu"
        ).to(device)
    return {"x": x}


def run(x, other):
    x |= other
    return x
